function notify(message,kind='success'){const dn=document.querySelector('#dialog-notice');if(dn){dn.textContent=message;dn.dataset.kind=kind;}const notice=document.querySelector('#notice');if(!notice)return;notice.textContent=message;notice.setAttribute('data-kind',kind);notice.setAttribute('role',kind==='error'?'alert':'status');const close=document.createElement('button');close.type='button';close.textContent='×';close.setAttribute('aria-label','Fechar notificação');close.setAttribute('data-action','dismiss-notice');notice.append(close);clearTimeout(notify.timer);if(kind!=='pending')notify.timer=setTimeout(()=>notice.textContent='',7000);}
function empty(title,desc=''){return `<div class="empty"><h3>${e(title)}</h3>${e(desc)}</div>`;}
function button(text,action,cls='primary'){return `<button type="button" class="${cls}" data-action="${action}">${text}</button>`;}
function field(label,name,type='text',value='',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${e(value)}" ${extra}></label>`;}
function select(label,name,options,value=''){return `<label>${label}<select name="${name}">${options.map(x=>{const [v,t]=Array.isArray(x)?x:[x,x];return `<option value="${e(v)}" ${String(value)===String(v)?'selected':''}>${e(t)}</option>`;}).join('')}</select></label>`;}
function area(label,name,value='',extra=''){return `<label class="full">${label}<textarea name="${name}" ${extra}>${e(value)}</textarea></label>`;}
function badge(text,color=''){return `<span class="badge ${color}">${e(text)}</span>`;}
const topicKey=t=>[t.career,t.subject,t.code].join('|');
function subjects(){return [...new Set(state.topics.filter(x=>x.career===(state.profile?.career||'CFO')).map(x=>x.subject))];}
const nameOf=id=>state.data.profiles.find(x=>x.id===id)?.name||'Aluno';
function allowed(){if(state.demo)return false;if(!api.configured){notify('Ative o Supabase para salvar. Esta visualização não grava dados.');return false;}return true;}
function guardWrite(){if(!allowed())throw Error('Prévia: conecte o Supabase para salvar dados reais.');}
function profilePick(value=''){return select('Aluno','student_id',state.data.profiles.filter(x=>x.role!=='admin').map(x=>[x.id,x.name+' · '+x.email]),value);}
function heading(title,desc='',action=''){return `<div class="heading"><div><div class="eyebrow">${admin()?'Painel do mentor':'Sua preparação'}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`;}
function landing(){app.innerHTML=`<header class="public-nav">${brand()}<nav><a href="#como-funciona">Como funciona</a><a href="#feedbacks">Alunos</a><a href="#planos">Planos</a><a class="btn" href="#login">Área do aluno ${icon('arrow')}</a></nav></header><main><section class="hero"><div><div class="eyebrow">Soldado & CFO · Polícia Militar da Bahia</div><h1>Seu estudo.<br>Seu ritmo.<br><span class="gold">Acompanhamento<br>de perto.</span></h1><p>Um ciclo que cabe na sua rotina. Direcionamento para as suas dificuldades e um lugar para acompanhar o que você está estudando.</p><div class="actions"><a class="btn primary" href="${whatsapp}" target="_blank" rel="noopener">Conversar sobre a mentoria ${icon('arrow')}</a><a class="btn" href="#planos">Conhecer os planos</a></div><p class="muted" style="margin-top:22px">Por quem está no CFO PMBA e conhece essa preparação.</p></div><div class="hero-panel"><div class="row"><span class="eyebrow">A preparação começa na sua rotina</span>${icon('cycle')}</div><div class="rule"></div><div class="row"><div><span class="big-number">01</span><p>Um plano individual.<br>Do primeiro estudo à revisão.</p></div><span class="badge">PMBA</span></div><div class="hero-task"><b>01</b><span>Você conta sua rotina<br><small>Horários, dificuldades e conteúdos já vistos</small></span></div><div class="hero-task"><b>02</b><span>Eu organizo o seu ciclo<br><small>Matérias e metas que fazem sentido para você</small></span></div><div class="hero-task"><b>03</b><span>A gente acompanha os registros<br><small>Questões, acertos e próximos ajustes</small></span></div><div class="actions"><a href="#login" class="btn" style="width:100%">Já sou aluno ${icon('arrow')}</a></div></div></section><section class="section" id="como-funciona"><div class="section-head"><div><div class="eyebrow">Organização, na prática</div><h2>O seu estudo, em um só lugar.</h2></div><p class="muted">Sem perder o acompanhamento individual.</p></div><div class="features"><article class="card"><span class="feature-no">01 /</span><h3>Um ciclo feito para você</h3><p>Horas disponíveis, matérias e observações reunidas nas suas tarefas. Saiba o que estudar e registre o que concluiu.</p></article><article class="card"><span class="feature-no">02 /</span><h3>Seu edital, assunto por assunto</h3><p>Marque estudo, resumo, questões e revisão. Veja o que já avançou em Soldado ou CFO PMBA.</p></article><article class="card"><span class="feature-no">03 /</span><h3>Desempenho que ajuda a decidir</h3><p>Registre questões feitas em outras plataformas e acompanhe acertos por matéria, assunto e período.</p></article></div></section><section class="section" id="feedbacks"><div class="section-head"><div><div class="eyebrow">Quem estuda com a mentoria</div><h2>O que os alunos estão dizendo.</h2></div><a class="btn small" href="${instagram}" target="_blank" rel="noopener">Ver no Instagram ${icon('arrow')}</a></div><div class="testimonials">${[1,2,3,4].map((n)=>`<a href="${siteAssets}/feedback-${n}.png" target="_blank" rel="noopener"><img src="${siteAssets}/feedback-${n}.png" alt="Feedback enviado por aluno da Mentoria alof.emacao, imagem ${n}" loading="lazy"><span>Abrir depoimento completo ↗</span></a>`).join('')}</div></section><section class="section" id="planos"><div class="section-head"><div><div class="eyebrow">Escolha seu acompanhamento</div><h2>Dois planos. Sua rotina como ponto de partida.</h2></div></div><div class="plans"><article class="card plan"><span class="eyebrow">Para se organizar</span><h3>Básico</h3><div class="price">R$ 49,90</div><ul><li>Ciclo individual de estudos</li><li>Edital verticalizado interativo</li><li>Registro de questões externas</li><li>Desempenho e histórico dos estudos</li></ul><p class="muted">Sem materiais, vídeos, questões, simulados e caderno de erros da plataforma.</p><div class="actions"><a class="btn" href="${whatsapp}" target="_blank" rel="noopener">Quero o Básico ${icon('arrow')}</a></div></article><article class="card plan featured"><span class="eyebrow">Para ter acompanhamento completo</span><h3>Estratégico</h3><div class="price">R$ 64,90</div><ul><li>Tudo do plano Básico</li><li>Materiais e vídeos</li><li>Questões comentadas e simulados</li><li>Caderno de erros e anotações</li><li>Ajustes e direcionamentos individuais</li></ul><p class="muted">Acesso completo aos conteúdos disponíveis na plataforma.</p><div class="actions"><a class="btn primary" href="${whatsapp}" target="_blank" rel="noopener">Quero o Estratégico ${icon('arrow')}</a></div></article></div><p class="muted" style="text-align:center;margin-top:24px">Combine os detalhes e a duração do acompanhamento pelo WhatsApp.</p></section><section class="section"><h2>Antes de entrar</h2><details><summary>Estou começando agora. Posso participar?</summary><p>Sim. O ciclo pode partir dos conteúdos básicos, considerando o que você já estudou e as horas disponíveis.</p></details><details><summary>Posso registrar questões feitas em outros sites?</summary><p>Sim, nos dois planos. Você informa a data, a matéria, o assunto, a quantidade de questões e os acertos.</p></details><details><summary>Como faço para contratar?</summary><p>O atendimento e a contratação são pelo WhatsApp. Depois da liberação do mentor, você acessa o plano contratado.</p></details></section></main><footer class="footer"><span>Mentoria alof.emacao · Soldado e CFO PMBA</span><span><a href="${instagram}" target="_blank" rel="noopener">Instagram</a> · <a href="${whatsapp}" target="_blank" rel="noopener">WhatsApp</a> · <a href="#login">Entrar</a></span></footer>`;}
function authPage(mode='login'){const register=mode==='cadastro',recovery=mode==='recuperar',change=mode==='nova-senha';app.innerHTML=`<div class="auth">${brand()}<div class="card"><div class="eyebrow">Mentoria alof.emacao</div><h1>${register?'Crie seu acesso':recovery?'Recuperar acesso':change?'Nova senha':'Bom ter você aqui.'}</h1><p class="muted">${register?'Após o cadastro, aguarde a liberação do mentor.':recovery?'A recuperação é feita pelo mentor, sem envio de e-mail.':'Entre para acompanhar seus estudos.'}</p>${!api.configured?'<div class="notice-box">Plataforma em ativação. Login e gravação serão liberados após conectar o Supabase.</div>':''}<form id="auth-form" data-mode="${mode}">${register?field('Seu nome','name','text','','required autocomplete="name"'):''}${!change?field('E-mail','email','email','','required autocomplete="email"'):''}${!recovery?field('Senha','password','password','','required minlength="'+(register||change?'8':'1')+'" autocomplete="'+(register||change?'new-password':'current-password')+'"'):''}${register||change?'<small>Use pelo menos 8 caracteres e uma senha exclusiva.</small>':''}<button class="primary" ${!api.configured?'disabled':''}>${register?'Criar meu acesso':recovery?'Solicitar ao administrador':change?'Salvar nova senha':'Entrar na plataforma'}</button></form><div class="auth-links"><a href="#${register||recovery?'login':'cadastro'}">${register||recovery?'Voltar ao login':'Criar acesso'}</a><a href="#recuperar">Esqueci a senha</a></div></div>${preview()?`<div class="card" style="margin-top:20px"><h3>Conferir a plataforma</h3><p class="muted">Prévia sem dados reais. As alterações não são salvas.</p><div class="actions">${button('Área do aluno','demo-student','')}${button('Administrativo','demo-admin','')}</div></div>`:''}<div class="actions"><a href="#">← Voltar ao site</a></div></div>`;}
async function loadData(){const tables=['profiles','cycles','progress','study_logs','history','resource_views','method_studies','method_reviews','study_sessions','cycle_days','flashcard_runs','topic_events'];if(premium())tables.push('flashcards');if(admin())tables.push('password_requests','method_templates');if(premium())tables.push('question_comments','questions','resources','exams','errors','question_notes','exam_attempts');const result=await Promise.all(tables.map(async t=>[t,await api.list(t)]));for(const [t,rows]of result)state.data[t]=rows;}
function enterDemo(role){state.demo=true;state.profile={id:'demo',name:role==='admin'?'Mentor':'Aluno de exemplo',role,plan:'Estratégico',active:true,career:'CFO'};state.data.profiles=[state.profile];location.hash='#painel/inicio';}
function shell(){const nav=[['inicio','home',admin()?'Visão geral':'Meu painel'],['ciclos','cycle',admin()?'Ciclos de estudos':'Meu ciclo'],['edital','book','Edital verticalizado'],['panorama','chart','Panorama dos estudos'],['dificuldades','chart','Dificuldades'],['desempenho','chart','Desempenho'],['registros','clock','Registro de estudos'],['historico','book','Histórico']];if(admin())nav.splice(1,0,['alunos','users','Alunos e acessos'],['metodos','book','Modelos de método']);const extras=[['questoes','question','Questões'],['erros','book','Caderno de erros'],['materiais','folder','Materiais e vídeos'],['simulados','cycle','Simulados'],['flashcards','book','Flashcards']];app.innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="nav-group">${admin()?'Gestão da mentoria':'Área do aluno'}</div><nav>${nav.map(x=>navLink(x)).join('')}</nav><div class="nav-group">Estudo e revisão</div><nav>${extras.map(x=>navLink(x,!premium())).join('')}</nav><div class="side-bottom"><a class="side-link" href="${whatsapp}" target="_blank" rel="noopener">${icon('question')} Falar no WhatsApp</a><a class="side-link" href="#">${icon('home')} Página inicial</a></div></aside><div class="workspace"><header class="topbar"><div class="inline-info"><span class="eyebrow">${admin()?'Central da mentoria':e(state.profile.career)+' PMBA'}</span><span class="status-text">${new Intl.DateTimeFormat('pt-BR',{dateStyle:'long',timeZone:'America/Bahia'}).format(new Date())}</span></div><div class="topbar-right">${badge(admin()?'Administrador':state.profile.plan)}<span class="avatar">${e(state.profile.name?.slice(0,2).toUpperCase())}</span>${button('Sair','logout','small subtle')}</div></header>${state.demo?'<div class="preview-banner">PRÉVIA · Sem dados reais. Você pode navegar e experimentar o gerador de ciclos, mas nada será salvo.</div>':''}<main class="content" id="content"></main></div></div>`;renderView();}
function navLink([id,ico,title],locked=false){return `<a class="side-link ${state.view===id?'active':''}" href="#painel/${id}" ${state.view===id?'aria-current="page"':''}>${icon(locked?'lock':ico)}${title}</a>`;}
function renderView(){const root=document.querySelector('#content');if(!root)return;if(!premium()&&['questoes','erros','materiais','simulados','flashcards'].includes(state.view)){root.innerHTML=heading('Recurso do Estratégico')+empty('Este recurso não está incluído no Básico','Seu ciclo, edital e registro de desempenho continuam disponíveis.')+`<div class="actions"><a class="btn primary" href="${whatsapp}" target="_blank" rel="noopener">Conversar sobre o Estratégico</a></div>`;return;}const views={inicio:dashboard,ciclos:cyclesPage,alunos:studentsPage,edital:editalPage,panorama:panoramaPage,desempenho:performancePage,registros:logsPage,historico:historyPage,questoes:questionsPage,erros:errorsPage,materiais:resourcesPage,simulados:examsPage,metodos:methodUI.methodsPage,dificuldades:methodUI.difficultiesPage,estudo:studyUI.page,flashcards:studyUI.flashPage};root.innerHTML=(views[state.view]||dashboard)();studyUI.afterRender();exportUI.controls();}
function stats(logs){const s=summarize(logs);return `<div class="stats"><div class="stat"><label>QUESTÕES REGISTRADAS</label><strong>${s.total}</strong><small>Plataforma + registros externos</small></div><div class="stat"><label>APROVEITAMENTO</label><strong>${s.total?s.rate+'%':'—'}</strong><small>${s.correct} certas · ${s.total-s.correct} erradas</small></div><div class="stat"><label>TEMPO REGISTRADO</label><strong>${Math.floor(s.minutes/60)}h ${s.minutes%60}m</strong><small>Tempo informado nos estudos</small></div><div class="stat"><label>DIAS COM REGISTRO</label><strong>${new Set(logs.map(x=>x.date)).size}</strong><small>Dentro do período selecionado</small></div></div>`;}
function dashboard(){const today=isoDay(),logs=state.data.study_logs;const cycles=state.data.cycles.filter(x=>x.status==='Publicado'),blocks=cycles.flatMap(c=>(c.blocks||[]).filter(x=>x.date===today).map(b=>({...b,cycle_id:c.id})));return heading(admin()?'Sua mentoria, por inteiro.':`Olá, ${e(state.profile.name.split(' ')[0])}.`,admin()?'Acompanhe registros, acessos e o que precisa da sua atenção.':'Confira o ciclo e registre o estudo de hoje.',`<a class="btn primary" href="#painel/${admin()?'ciclos':'registros'}">${admin()?'+ Criar ciclo':'+ Registrar estudo'}</a>`)+stats(logs)+`<div class="grid-main"><div class="card"><div class="row"><h2>${admin()?'Alunos para acompanhar':'Seu dia de estudo'}</h2>${admin()?badge(today.split('-').reverse().join('/')):''}</div><div class="rule"></div>${admin()?studentRows(true):studyUI.dashboard()}<div class="actions"><a class="btn small" href="#painel/${admin()?'alunos':'ciclos'}">${admin()?'Ver todos os alunos':'Ver ciclo completo'} ${icon('arrow')}</a></div></div><div class="stack"><div class="card"><span class="eyebrow">Acompanhamento por matéria</span><h2 style="margin-top:8px">Onde concentrar a atenção</h2>${subjectBars(logs)}</div><div class="card"><span class="eyebrow">Próximos passos</span><h3 style="margin:10px 0">${admin()?'Organize antes de publicar':'Continue de onde parou'}</h3><p>${admin()?'Defina o plano de cada aluno e revise os assuntos sugeridos antes de liberar o ciclo.':'Abra o assunto do seu dia. Ao concluir as etapas, o edital e o histórico serão atualizados.'}</p><a class="btn small" style="margin-top:20px" href="#painel/edital">Abrir edital ${icon('arrow')}</a></div></div></div>`;}
function subjectBars(logs){const ss=[...new Set(logs.map(x=>x.subject))];return ss.length?ss.map(s=>{const m=summarize(logs.filter(x=>x.subject===s));return `<div class="bar-row"><span>${e(s)}</span><div class="progress"><span style="width:${m.rate}%"></span></div><span>${m.rate}%</span></div>`;}).join(''):empty('Sem dados ainda','Os percentuais serão calculados com os registros.');}
function studentRows(compact=false){const students=state.data.profiles.filter(x=>x.role!=='admin');if(!students.length)return empty('Seus alunos aparecerão aqui','Após criar a própria conta, cada aluno aguarda sua liberação.');return `<div class="table-wrap"><table><thead><tr><th>Aluno</th><th>Plano</th><th>Acompanhamento</th>${compact?'':'<th>Acesso</th><th>Editar</th>'}</tr></thead><tbody>${students.map(p=>`<tr><td>${e(p.name)}<small>${e(p.email)}</small></td><td>${badge(p.plan)}</td><td>${e(studentAlert(p,state.data.study_logs))}</td>${compact?'':`<td>${p.active?'Liberado':'Aguardando'}</td><td><button class="small" data-action="edit-student" data-id="${p.id}">Editar</button></td>`}</tr>`).join('')}</tbody></table></div>`;}
function studentsPage(){if(!admin())return empty('Acesso reservado ao mentor');return heading('Alunos e acessos','Libere o plano somente após confirmar a contratação.')+studentRows()+passwordRequests()+`<div id="student-editor"></div>`;}
function studentEditor(p){document.querySelector('#student-editor').innerHTML=`<form id="student-form" data-id="${p.id}" class="card fields" style="margin-top:25px"><h2 class="full">Editar ${e(p.name)}</h2>${field('Nome','name','text',p.name,'required')}${select('Plano','plan',['Básico','Estratégico'],p.plan)}${select('Concurso','career',['CFO','Soldado'],p.career)}${select('Acesso','active',[['true','Liberado'],['false','Bloqueado']],String(p.active))}<button class="primary">Salvar alterações</button></form><form id="admin-password-form" data-id="${p.id}" class="card fields" style="margin-top:20px"><h2 class="full">Definir nova senha</h2>${field('Nova senha (mínimo 8 caracteres)','password','password','','required minlength="8" maxlength="128" autocomplete="new-password"')}<button class="primary">Atualizar senha do aluno</button><p class="muted full">Entregue a senha ao aluno pelo contato combinado. Nenhum e-mail será enviado.</p></form><div class="card" style="margin-top:20px"><h3>Excluir aluno</h3><p>Exclui a conta, ciclos, desempenho, anotações e histórico deste aluno. Não pode ser desfeito.</p><button type="button" data-action="delete-student" data-id="${p.id}">Excluir ${e(p.name)}</button></div>`;}
function taskRow(b){const key=b.cycle_id+'|'+b.id,p=state.data.progress.find(p=>p.key===key),done=p?.flags?.done;return `<div class="task ${done?'done':''}"><input aria-label="Concluir ${e(b.subject)}" type="checkbox" data-task="${e(key)}" ${done?'checked':''} ${admin()?'disabled':''}><div class="task-text"><h3>${e(b.subject)} · ${e(b.topic)}</h3><small>${e(dayLabel(b.date,state.data.cycles.find(c=>c.id===b.cycle_id)?.start_date||state.data.cycles.find(c=>c.id===b.cycle_id)?.blocks.map(x=>x.date).sort()[0]||b.date))}${b.notes?' · '+e(b.notes):''}</small></div><span class="badge">${b.minutes} min</span></div>`;}
function cyclesPage(){if(!admin())return methodUI.board();return heading('Ciclos de estudos','Sugestão por horas e matérias, com revisão manual antes da publicação.')+`<div class="card"><form id="generate-cycle" class="fields">${profilePick()}${field('Nome do ciclo','title','text','Ciclo de estudos','required')}<input type="hidden" name="start" value="${isoDay()}">${field('Dias do ciclo (1 a 365)','days','number',30,'min="1" max="365" required')}${methodUI.templateSelect()}${field('Horas por dia','hours','number',3,'min="0.5" max="16" step="0.5" required')}${field('Matérias por dia','count','number',2,'min="1" max="30" required')}<div class="full cycle-subjects">${select('Edital do aluno (definido no cadastro)','cycle_career',['CFO','Soldado'],state.data.profiles.find(x=>x.role!=='admin')?.career||'CFO').replace('<select','<select disabled')}<p class="muted">Marque todas as matérias que deseja distribuir durante o período. “Matérias por dia” define quantas entram em cada dia.</p><div class="actions">${button('Selecionar todas','cycle-select-all','small')}${button('Limpar seleção','cycle-select-none','small')}<span id="cycle-selection-count" aria-live="polite">Nenhuma matéria selecionada</span></div><div id="cycle-subject-options" class="check-grid">${cycleSubjectOptions(state.data.profiles.find(x=>x.role!=='admin')?.career||'CFO')}</div></div>${area('Observações gerais','notes')}<button class="primary" type="submit">Gerar sugestão editável</button>${state.data.profiles.some(x=>x.role!=='admin')?'':'<p class="notice-box full">Ainda não há alunos cadastrados. O aluno precisa criar seu acesso para você vincular e salvar o ciclo.</p>'}</form></div><div id="cycle-draft"></div><h2 style="margin:30px 0 18px">Ciclos anteriores</h2>${state.data.cycles.length?state.data.cycles.map(c=>`<div class="card row" style="margin:12px 0"><div><h3>${e(c.title)}</h3><small>${e(nameOf(c.student_id))} · ${c.blocks.length} blocos</small></div>${badge(c.status)}<div class="actions"><button class="small" data-action="edit-cycle" data-id="${c.id}">Editar</button><button class="small" data-action="renew-cycle" data-id="${c.id}">Renovar</button><button class="small" data-action="continue-cycle" data-id="${c.id}">Continuar</button></div></div>`).join(''):empty('Nenhum ciclo salvo')}`;}
function draftTopics(){const student=state.data.profiles.find(p=>p.id===state.draftMeta?.student_id);return state.topics.filter(t=>t.career===student?.career);}
function renderDraft(meta){state.draftMeta=meta;state.draftStart=meta.start_date||meta.start||state.draftStart||state.draft.map(b=>b.date).sort()[0]||isoDay();const topics=draftTopics(),ss=[...new Set(topics.map(t=>t.subject))],dates=[...new Set(state.draft.map(b=>b.date))].sort();state.draftDay=state.draftDay||dates[0]||isoDay();const own=state.draft.filter(b=>b.date===state.draftDay);document.querySelector('#cycle-draft').innerHTML=`<form id="save-cycle" class="card" style="margin-top:25px"><h2>Revise cada dia · ${e(nameOf(meta.student_id))}</h2><p class="muted">Escolha um dia e ajuste a quantidade, as matérias, os assuntos e os minutos. Continuar mantém este ciclo e o ponto em que o aluno parou. Renovar cria outro ciclo seguindo o edital. Os ciclos anteriores são preservados.</p><div class="fields">${field('Nome do ciclo','draft_title','text',meta.title,'required')}${area('Observações gerais','draft_notes',meta.notes)}${field('Total de dias do ciclo','draft_days','number',meta.duration_days||30,'required min="1" max="365"')}<label>Dia de estudo<input type="number" id="draft-day" min="1" max="365" value="${dayNumber(state.draftDay,state.draftStart)}" required></label><label>Matérias neste dia<input type="number" id="day-count" min="0" max="${ss.length}" value="${own.length}"></label></div><p>${own.length} blocos · ${own.reduce((a,b)=>a+b.minutes,0)} minutos no dia selecionado. Quantidade 0 deixa o dia livre.</p><div id="draft-rows">${state.draft.map((b,i)=>b.date!==state.draftDay?'':`<div class="cycle-item" data-index="${i}"><strong>${dayLabel(b.date,state.draftStart)}</strong>${select('Matéria','subject',ss,b.subject)}${select('Assunto do edital','topic_key',[['follow','Seguir edital verticalizado'],['','Selecione um assunto'],...topics.filter(t=>t.subject===b.subject).map(t=>[syllabusKey(t),t.code+' · '+t.title])],b.topic_key||syllabusKey(topics.find(t=>t.subject===b.subject&&t.title===b.topic)||{}))}<label>Minutos<input name="minutes" type="number" min="1" max="960" value="${b.minutes}" required></label><label>Observações<input name="notes" value="${e(b.notes)}"></label><button type="button" class="small" data-action="remove-block" data-index="${i}">Remover</button></div>`).join('')}</div><div class="actions">${button('+ Adicionar matéria neste dia','add-block','')}<button name="status" value="Rascunho">Salvar rascunho</button><button class="primary" name="status" value="Publicado">Publicar para o aluno</button></div><div class="continuation-tools"><label>Acrescentar dias seguindo sua organização<input name="extend_days" type="number" value="30" min="1" max="364"></label>${button("Acrescentar dias ao ciclo","extend-cycle","")}<p class="muted">Mantém as matérias e os minutos de cada dia como modelo. Os próximos assuntos seguem o edital. Revise as recomendações antes de publicar.</p></div><details><summary>Ver todos os dias · ${dates.length} dias · ${state.draft.length} blocos</summary>${dates.map(d=>`<div class="task"><button type="button" class="small" data-action="select-draft-day" data-date="${d}">${dayLabel(d,state.draftStart)}</button><span>${e(state.draft.filter(b=>b.date===d).map(b=>b.subject).join(' · '))}</span></div>`).join('')}</details></form>`;methodUI.draftButtons();}

function captureDraft(){const days=document.querySelector('[name="draft_days"]');if(days&&state.draftMeta)state.draftMeta.duration_days=+days.value;const form=document.querySelector('#save-cycle');if(!form)return;state.draftMeta.title=form.elements.draft_title.value;state.draftMeta.notes=form.elements.draft_notes.value;document.querySelectorAll('.cycle-item').forEach(el=>{const b=state.draft[Number(el.dataset.index)];el.querySelectorAll('input,select').forEach(input=>b[input.name]=input.name==='minutes'?Number(input.value):input.value);const t=draftTopics().find(t=>syllabusKey(t)===b.topic_key&&t.subject===b.subject);b.topic=b.topic_key==='follow'?'Seguir edital verticalizado':t?.title||'';});}
function addDayBlock(){const topics=draftTopics(),ss=[...new Set(topics.map(t=>t.subject))],own=state.draft.filter(b=>b.date===state.draftDay),subject=ss.find(s=>!own.some(b=>b.subject===s));if(!subject)throw Error('Todas as matérias do edital já estão neste dia.');const b=assignTopics([{id:crypto.randomUUID(),date:state.draftDay,subject,minutes:30,notes:''}],topics,state.data.progress,state.draftMeta.student_id)[0];state.draft.push(b);}
document.addEventListener('change',event=>{const el=event.target;if(!el.closest('#save-cycle'))return;try{captureDraft();if(el.id==='draft-day')state.draftDay=dayDate(Number(el.value),state.draftStart);else if(el.id==='day-count'){const count=Number(el.value),max=new Set(draftTopics().map(t=>t.subject)).size;if(!Number.isInteger(count)||count<0||count>max)throw Error('Quantidade inválida para este edital.');while(state.draft.filter(b=>b.date===state.draftDay).length>count){const i=state.draft.findLastIndex(b=>b.date===state.draftDay);state.draft.splice(i,1);}while(state.draft.filter(b=>b.date===state.draftDay).length<count)addDayBlock();}else if(el.name==='subject'){const b=state.draft[Number(el.closest('.cycle-item').dataset.index)],t=draftTopics().find(t=>t.subject===b.subject);b.topic=t.title;b.topic_key=syllabusKey(t);}else return;renderDraft(state.draftMeta);}catch(err){notify(err.message,'error');}finally{delete el.dataset.busy;el.removeAttribute('aria-busy');}});
function editalPage(){const student=admin()?(state.data.profiles.find(p=>p.id===state.filter.student_id)||state.data.profiles.find(p=>p.role!=='admin')):state.profile;if(!student)return heading('Edital verticalizado')+empty('Cadastre um aluno para acompanhar');const career=student.career,ss=[...new Set(state.topics.filter(t=>t.career===career).map(t=>t.subject))],subject=ss.includes(state.filter.subject)?state.filter.subject:ss[0],tt=state.topics.filter(t=>t.career===career&&t.subject===subject);return heading('Edital verticalizado',student.name+' · '+career+' · Etapas sincronizadas com o plano de estudos.')+`<form id="edital-filter" class="toolbar">${admin()?profilePick(student.id):''}${select('Matéria','subject',ss,subject)}<button>Filtrar</button></form><div class="table-wrap"><table><thead><tr><th>Assunto e histórico</th>${['Estudo','Resumo','Questões','Revisão','Flashcards'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${tt.map(t=>{const key='edital|'+topicKey(t),p=state.data.progress.find(p=>p.student_id===student.id&&p.key===key);return `<tr><td><button class="topic-history-link" data-action="topic-history" data-topic="${e(topicKey(t))}" data-student="${student.id}"><small>${e(t.code)}</small>${e(t.title)}</button></td>${['study','summary','questions','review','flashcards'].map(flag=>`<td><input aria-label="${flag}: ${e(t.title)}" type="checkbox" data-edital="${e(key)}" data-flag="${flag}" ${p?.flags?.[flag]?'checked':''} ${admin()||flag==='flashcards'?'disabled':''}></td>`).join('')}</tr>`;}).join('')}</tbody></table></div>`;}
function filters(){const f=state.filter;return `<form id="performance-filter" class="toolbar">${select('Período','period',[['all','Todo o histórico'],['day','Hoje'],['week','Últimos 7 dias'],['month','Mês atual']],f.period||'all')}${select('Matéria','subject',[['','Todas'],...[...new Set(state.data.study_logs.map(x=>x.subject))]],f.subject||'')}${field('Assunto','topic','text',f.topic||'')}${admin()?select('Aluno','student_id',[['','Todos'],...state.data.profiles.filter(x=>x.role!=='admin').map(x=>[x.id,x.name])],f.student_id||''):''}<button>Aplicar filtros</button></form>`;}
function filteredLogs(){const f=state.filter,today=isoDay();return state.data.study_logs.filter(r=>(!f.subject||r.subject===f.subject)&&(!f.topic||r.topic.toLowerCase().includes(f.topic.toLowerCase()))&&(!f.student_id||r.student_id===f.student_id)&&(!f.period||f.period==='all'||f.period==='day'&&r.date===today||f.period==='month'&&r.date.slice(0,7)===today.slice(0,7)||f.period==='week'&&Date.parse(today)-Date.parse(r.date)<7*86400000&&r.date<=today));}
function performancePage(){const rows=filteredLogs();return heading('Desempenho','Aproveitamento calculado pelo total de acertos dividido pelo total de questões.')+filters()+stats(rows)+`<div class="card"><h2>Acertos por matéria</h2>${subjectBars(rows)}</div><h2 style="margin:25px 0 15px">Registros do período</h2>`+logTable(rows)+(admin()&&!state.filter.student_id?'':studyUI.flashStats(state.filter.student_id||state.profile.id)+studyUI.dayHistory(state.filter.student_id||state.profile.id));}
function logTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Dia</th>${admin()?'<th>Aluno</th>':''}<th>Matéria / assunto</th><th>Fonte</th><th>Questões</th><th>Acertos</th><th>Tempo</th></tr></thead><tbody>${[...rows].sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<tr><td>${e(r.date.split('-').reverse().join('/'))}</td>${admin()?`<td>${e(nameOf(r.student_id))}</td>`:''}<td>${e(r.subject)}<small>${e(r.topic)}</small></td><td>${e(r.source)}${r.notes?'<small>'+e(r.notes)+'</small>':''}</td><td>${r.total}</td><td>${r.correct}</td><td>${r.minutes} min</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum registro neste período');}
function logsPage(){return heading('Registro de estudos','Inclua questões feitas em outros sites, livros ou PDFs, sem precisar copiar os enunciados.')+`<form id="log-form" class="card fields">${admin()?profilePick():''}${field('Data','date','date',isoDay(),'required max="'+isoDay()+'"')}${select('Assunto do edital (opcional)','log_topic_key',[['','Preencher matéria e assunto manualmente'],...state.topics.filter(t=>t.career===(admin()?state.data.profiles.find(p=>p.role!=='admin')?.career:state.profile.career)).map(t=>[syllabusKey(t),t.subject+' · '+t.title])])}${field('Matéria / disciplina','subject','text','','required list="subjects"')}${field('Assunto','topic','text','','required')}${field('Fonte (ex.: QConcursos)','source','text','','required')}${field('Quantidade de questões','total','number',10,'required min="0"')}${field('Acertos','correct','number',0,'required min="0"')}${field('Tempo estudado (minutos)','minutes','number',0,'required min="0" max="1440"')}${area('Observações sobre este registro','notes')}${premium()?select('Motivo dos erros (opcional)','error_reason',[['','Não registrar motivo'],'Falta de conteúdo','Interpretação','Desatenção','Esquecimento','Cálculo','Outro']):''}<p class="full muted">Se o Pomodoro já registrou esse tempo, deixe os minutos em zero para evitar duplicidade.</p><datalist id="subjects">${subjects().map(s=>`<option value="${e(s)}">`).join('')}</datalist><button class="primary">Salvar registro</button></form><h2 style="margin:30px 0 18px">Últimos registros</h2>`+logTable(state.data.study_logs);}
function historyPage(){return heading('Histórico','Ciclos, registros e observações, organizados por aluno.')+(admin()?`<form id="history-form" class="card fields" style="margin-bottom:25px">${profilePick()}${field('Título','title','text','','required')}${area('Observações do acompanhamento','body','','required')}<label class="check-label"><input name="visible" type="checkbox" checked>Aluno pode ver esta observação</label><button class="primary">Adicionar ao histórico</button></form>`:'')+(state.data.history.map(h=>`<article class="card" style="margin-bottom:15px"><small>${new Date(h.created_at).toLocaleDateString('pt-BR')} ${admin()?'· '+e(nameOf(h.student_id)):''} ${h.visible?'':'· Privado do mentor'}</small><h3 style="margin-top:10px">${e(h.title)}</h3><div class="private-note">${e(h.body)}</div></article>`).join('')||empty('Nenhuma observação registrada'))+`<div class="actions"><a class="btn" href="#painel/ciclos">Ciclos anteriores</a><a class="btn" href="#painel/desempenho">Histórico de desempenho</a></div><h2 style="margin-top:30px">Materiais acessados</h2>`+(state.data.resource_views.length?state.data.resource_views.map(v=>`<div class="task"><span>${e(nameOf(v.student_id))}</span><span>${e(state.data.resources.find(r=>r.id===v.resource_id)?.title||'Material')}</span><small>${new Date(v.created_at).toLocaleDateString('pt-BR')}</small></div>`).join(''):empty('Nenhum acesso registrado'));}
function questionForm(q={}){return `<form id="question-form" data-id="${q.id||''}" class="card fields" style="margin-bottom:25px"><h2 class="full">${q.id?'Editar questão':'Nova questão'}</h2>${field('Matéria','subject','text',q.subject||'','required')}${field('Assunto','topic','text',q.topic||'','required')}${field('Banca / autoria','board','text',q.board||'')}${field('Ano','year','number',q.year||new Date().getFullYear(),'min="1900" max="2100"')}${select('Dificuldade','difficulty',['Fácil','Média','Difícil'],q.difficulty||'Média')}${field('Tags, separadas por vírgulas','tags','text',q.tags||'')}${area('Enunciado','body',q.body||'','required')}${area('Alternativas, uma por linha','options',(q.options||[]).join('\n'),'required placeholder="Alternativa A\nAlternativa B\nAlternativa C\nAlternativa D\nAlternativa E"')}${select('Gabarito','correct_index',[[0,'A'],[1,'B'],[2,'C'],[3,'D'],[4,'E']],q.correct_index??0)}${field('Fonte / referência','source','text',q.source||'')}${area('Comentário do gabarito','explanation',q.explanation||'','required')}<label class="check-label full"><input type="checkbox" name="authorized" required>Tenho autorização para publicar este conteúdo.</label><button class="primary">Salvar questão</button></form>`;}
function questionsPage(){if(state.activeQuestion)return questionDetail();const qs=state.data.questions.filter(q=>(!state.filter.subject||q.subject.toLowerCase().includes(state.filter.subject.toLowerCase()))&&(!state.filter.topic||q.topic.toLowerCase().includes(state.filter.topic.toLowerCase())));return heading('Questões','Enunciado, grifos, anotações privadas e análise após responder.')+(admin()?questionForm(state.editQuestion||{}):'')+`<form id="question-filter" class="toolbar">${field('Matéria','subject','text',state.filter.subject||'')}${field('Assunto','topic','text',state.filter.topic||'')}<button>Filtrar</button></form>`+(qs.length?qs.map(q=>`<article class="card row" style="margin:14px 0"><div>${badge(q.difficulty)}<h3 style="margin-top:10px">${e(q.subject)} · ${e(q.topic)}</h3><small>${e(q.board)} ${e(q.year)} · ${e(q.body.slice(0,100))}</small></div><div class="actions">${canReviewQuestion(q.id)?`<button class="small" data-action="open-question" data-id="${q.id}">Resolver</button>`:'<span class="badge">Disponível após finalizar o simulado</span>'}${admin()?`<button class="small" data-action="edit-question" data-id="${q.id}">Editar</button>`:''}</div></article>`).join(''):empty('Seu banco de questões começa aqui',admin()?'Cadastre o primeiro enunciado no formulário acima.':'O mentor ainda não publicou questões.'));}
function questionDetail(){const q=state.activeQuestion,note=state.data.question_notes.find(x=>x.question_id===q.id);return heading('Mesa de questões',e(q.subject)+' · '+e(q.topic),button('Voltar ao banco','close-question',''))+`<article class="card question"><div class="row"><span>${badge(q.difficulty)} ${e(q.board)} · ${e(q.year)}</span><span class="muted">${e(q.source)}</span></div><div class="question-tools">${button('Grifar seleção','highlight','small')}${button('Limpar grifos','clear-highlight','small')}<small>Selecione um trecho do enunciado e clique em grifar.</small></div><div class="question-text" id="question-body">${highlightBody(q.body,note?.highlights||[])}</div><form id="answer-form">${q.options.map((o,i)=>`<label class="option"><input type="radio" name="answer" value="${i}" required ${state.answer===i?'checked':''}><strong>${String.fromCharCode(65+i)}</strong><span>${e(o)}</span></label>`).join('')}<div class="actions"><button class="primary">Responder e analisar</button>${button('Adicionar ao caderno de erros','question-error','')}</div></form><div id="question-result"></div><form id="note-form" style="margin-top:25px">${area('Suas anotações privadas','body',note?.body||'')}<button class="small" style="margin-top:12px">Salvar anotação e grifos</button></form>${questionComments(q.id)}</article>`;}
function highlightBody(text,ranges){const safe=ranges.filter(r=>Number.isInteger(r.start)&&Number.isInteger(r.end)&&r.start>=0&&r.end<=text.length&&r.start<r.end).sort((a,b)=>a.start-b.start);let out='',pos=0;for(const r of safe){if(r.start<pos)continue;out+=e(text.slice(pos,r.start))+'<mark>'+e(text.slice(r.start,r.end))+'</mark>';pos=r.end;}return out+e(text.slice(pos));}
function richField(label,name,value='',required=false){return `<div class="full"><label>${label}<textarea name="${name}" ${required?'required':''}>${e(value)}</textarea></label><div class="actions">${[['Negrito','**'],['Itálico','*'],['Sublinhar','__'],['Destacar','=='],['Lista','- ']].map(([label,mark])=>`<button type="button" class="small" data-action="format-error" data-field="${name}" data-mark="${mark}">${label}</button>`).join('')}</div><small>Selecione um trecho e escolha a formatação.</small><div class="private-note" data-rich-preview="${name}">${formattedText(value)}</div></div>`;}
function errorsPage(){const edit=state.editError||{};return heading('Caderno de erros','Anote o que errou, por quê e o que revisar.')+`<form id="error-form" data-id="${edit.id||''}" class="card fields">${field('Matéria','subject','text',edit.subject||'','required')}${field('Assunto','topic','text',edit.topic||'','required')}${select('Motivo do erro','reason',['Falta de conteúdo','Interpretação','Desatenção','Esquecimento','Cálculo','Outro'],edit.reason)}${field('Fonte ou link da questão','source','text',edit.source||'')}${richField('Questão ou referência do erro','body',edit.body||'',true)}${richField('O que revisar / explicação','explanation',edit.explanation||'')}<button class="primary">${edit.id?'Salvar edição':'Salvar no caderno'}</button></form><form id="error-filter" class="toolbar" style="margin-top:25px">${field('Matéria','subject','text',state.filter.subject||'')}${field('Assunto','topic','text',state.filter.topic||'')}${select('Motivo','reason',[['','Todos'],'Falta de conteúdo','Interpretação','Desatenção','Esquecimento','Cálculo','Outro'],state.filter.reason||'')}<button>Filtrar</button></form>`+(state.data.errors.filter(x=>(!state.filter.subject||x.subject.toLowerCase().includes(state.filter.subject.toLowerCase()))&&(!state.filter.topic||x.topic.toLowerCase().includes(state.filter.topic.toLowerCase()))&&(!state.filter.reason||x.reason===state.filter.reason)).map(x=>`<div class="card" style="margin:15px 0"><div class="row"><h3>${e(x.subject)} · ${e(x.topic)}</h3>${badge(x.reason)}</div><p>${formattedText(x.body)}</p><div class="private-note">${formattedText(x.explanation)}</div><small>${e(x.source)}</small><div class="actions">${x.student_id===state.profile.id?`<button class="small" data-action="review-error" data-id="${x.id}">${x.reviewed?'Marcar como pendente':'Marcar como revisado'}</button>`:'<small>Marcação de revisão feita pelo aluno.</small>'}${x.student_id===state.profile.id?`<button class="small" data-action="edit-error" data-id="${x.id}">Editar texto</button>`:''}${x.reviewed?badge('Revisado','green'):''}</div></div>`).join('')||empty('Nenhum erro registrado'));}

function resourcesPage(){if(!admin())return methodUI.resourcePage();return heading('Materiais e vídeos','Conteúdos liberados para o plano Estratégico.')+(admin()?`<form id="resource-form" class="card fields" style="margin-bottom:25px">${field('Título','title','text','','required')}${select('Tipo','kind',['Material','Vídeo'])}${field('Matéria','subject','text','','required')}${field('Link (opcional se enviar arquivo)','url','url')}${field('Arquivo (até 50 MB)','file','file','','accept=".pdf,.mp4,.webm,.png,.jpg,.jpeg,.docx,.xlsx"')}${area('Descrição','description')}<button class="primary">Publicar conteúdo</button></form>`:'')+`<div class="asset-list">${state.data.resources.map(r=>`<article class="card"><span class="eyebrow">${e(r.kind)} · ${e(r.subject)}</span><h3>${e(r.title)}</h3><p>${e(r.description)}</p><button class="btn" data-action="open-resource" data-id="${r.id}">${r.kind==='Vídeo'?'Assistir ao vídeo':'Abrir material'} ${icon('arrow')}</button></article>`).join('')}</div>`+(state.data.resources.length?'':empty('Nenhum conteúdo publicado'));}
function examsPage(){if(state.exam)return examDetail();const draft=state.examDraft||{title:'Simulado '+(Math.max(0,...state.data.exams.map(x=>Number(x.title.match(/^Simulado (\d+)/)?.[1]||0)))+1),duration:120,description:'',question_ids:[]};return heading('Simulados','Monte o simulado, cadastre questões comentadas e acompanhe os resultados.')+(admin()?`<form id="exam-form" class="card fields" style="margin-bottom:25px">${select('Edital do simulado','career',[['','Selecione'],['CFO','CFO'],['Soldado','Soldado']],draft.career||'').replace('<select','<select required')}${field('Nome do simulado','title','text',draft.title,'required')}${field('Duração (minutos)','duration','number',draft.duration,'min="10" max="360" required')}${area('Orientações','description',draft.description)}<div class="full"><h3>Questões do banco</h3><p>Marque as questões ou cadastre novas abaixo. Toda questão criada aqui também fica no banco da plataforma.</p></div><div class="full check-grid">${state.data.questions.map(q=>`<label class="check-label"><input name="questions" type="checkbox" value="${q.id}" ${draft.question_ids.includes(q.id)?'checked':''}>${e(q.subject+' · '+q.topic+' · '+q.body.slice(0,100))}</label>`).join('')||'<p class="muted">Cadastre a primeira questão abaixo.</p>'}</div><div class="actions full">${button('+ Criar questão para este simulado','compose-exam-question','')}<button class="primary">${state.editExam?'Salvar simulado':'Publicar simulado'}</button></div></form>${state.examComposer?questionForm().replace('id="question-form"','id="question-form" data-exam-composer="true"'):''}`:'')+`<form id="exam-filter" class="toolbar">${select('Edital','exam_career',[['','Todos'],['CFO','CFO'],['Soldado','Soldado'],['unclassified','A classificar']],state.filter.exam_career||'')}<button>Filtrar</button></form>`+(state.data.exams.filter(x=>!state.filter.exam_career||(state.filter.exam_career==='unclassified'?!x.career:x.career===state.filter.exam_career)).map(x=>`<article class="card row" style="margin:15px 0"><div><h3>${e(x.title)} · ${e(x.career||'Definir edital')}</h3><p>${e(x.description)}</p><small>${x.question_ids.length} questões · ${x.duration} minutos</small></div><div class="actions"><button class="primary" data-action="start-exam" data-id="${x.id}">Iniciar simulado</button>${admin()||state.data.exam_attempts.some(a=>a.exam_id===x.id&&a.student_id===state.profile.id&&a.submitted_at)?`<button data-action="print-exam" data-id="${x.id}">Imprimir com gabarito</button>`:'<small>Finalize para liberar gabarito e impressão.</small>'}${admin()?`<button data-action="edit-exam" data-id="${x.id}">Editar</button><button data-action="delete-exam" data-id="${x.id}">Excluir</button>`:''}</div></article>`).join('')||empty('Nenhum simulado publicado'))+`<h2 style="margin:30px 0 20px">Resultados anteriores</h2>`+(state.data.exam_attempts.map(x=>`<details><summary>${e(state.data.exams.find(a=>a.id===x.exam_id)?.title||'Simulado')} · ${admin()?e(nameOf(x.student_id))+' · ':''}${x.score??'Em andamento'} ${x.score!==null?'acertos':''}</summary>${(x.details||[]).map((r,i)=>resultQuestion(r,i)).join('')}</details>`).join('')||empty('Nenhum simulado realizado'));}

function examDetail(){const ex=state.exam,qs=ex.questions||ex.question_ids.map(id=>state.data.questions.find(q=>q.id===id)).filter(Boolean);if(state.result)return heading('Resultado do simulado')+`<div class="card"><h2>${state.result.score} de ${state.result.total} acertos</h2><p>Resultado salvo no seu desempenho. Questões em branco contam como erro.</p>${state.result.details.map(resultQuestion).join('')}${button('Voltar aos simulados','close-exam','primary')}</div>`;return heading(e(ex.title),'Seu tempo é contado no servidor a partir do início. Questões em branco contam como erro.')+`<div class="notice-box">Finalização até ${new Date(ex.deadline).toLocaleTimeString('pt-BR')} · ${ex.duration} minutos. Envie antes de fechar a página.</div><form id="exam-submit">${qs.map((q,n)=>`<article class="card question" style="margin-bottom:20px"><span class="eyebrow">Questão ${n+1} · ${e(q.subject)}</span><div class="question-text">${e(q.body)}</div>${q.options.map((o,i)=>`<label class="option"><input type="radio" name="${q.id}" value="${i}" ${state.examAnswers[q.id]===i?'checked':''}><strong>${String.fromCharCode(65+i)}</strong><span>${e(o)}</span></label>`).join('')}</article>`).join('')}<button class="primary">Finalizar e corrigir simulado</button></form>`;}
async function route(){methodUI.closeDialog();document.querySelector('#study-dialog')?.remove();document.querySelector('#export-dialog')?.remove();const hash=location.hash.slice(1);if(['como-funciona','feedbacks','planos'].includes(hash)){landing();document.getElementById(hash)?.scrollIntoView({behavior:'smooth'});return;}if(hash.startsWith('painel')){if(!state.profile){authPage();return;}if(!state.profile.active){app.innerHTML=`<div class="auth">${brand()}${empty('Aguardando liberação','Seu cadastro foi recebido. O mentor precisa liberar seu plano.')}<div class="actions"><a class="btn primary" href="${whatsapp}" target="_blank" rel="noopener">Falar com o mentor</a>${button('Sair','logout','')}</div></div>`;return;}state.view=hash.split('/')[1]||'inicio';state.filter={};state.activeQuestion=null;state.editQuestion=null;state.exam=null;state.result=null;shell();return;}if(['login','cadastro','recuperar','nova-senha'].includes(hash)){authPage(hash);return;}landing();}
async function writeAndReload(table,data,id){guardWrite();await api.save(table,data,id);await loadData();notify('Salvo com sucesso.');renderView();}
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,fd=new FormData(form),v=Object.fromEntries(fd),submitter=event.submitter;if(form.dataset.busy)return;form.dataset.busy='true';submitter?.setAttribute('disabled','');notify('Processando sua solicitação…','pending');try{
 if(await studyUI.submit(form,fd))return;
 if(await methodUI.submit(form,fd))return;
 if(form.id==='auth-form'){const status=document.createElement('p');status.className='notice-box';status.setAttribute('role','status');status.id='auth-status';document.querySelector('#auth-status')?.remove();form.append(status);status.textContent='Aguarde, verificando seu acesso…';const mode=form.dataset.mode;if(mode==='login'){state.user=await api.login(v.email.trim(),v.password);state.profile=(await api.list('profiles','id=eq.'+state.user.id))[0];if(!state.profile)throw Error('Perfil não encontrado. Confirme a configuração do banco.');state.demo=false;await loadData();location.hash='#painel/inicio';await route();notify('Login realizado com sucesso.');}else if(mode==='cadastro'){const result=await api.signup(v.email,v.password,v.name);authPage('login');const info=document.createElement('p');info.className='notice-box';info.setAttribute('role','status');info.textContent='Cadastro criado. Entre com seu e-mail e senha e aguarde a liberação do mentor. Não é necessário confirmar por e-mail.';document.querySelector('#auth-form').before(info);history.replaceState(null,'','#login');notify('Cadastro criado. Aguarde a liberação do mentor.');}else if(mode==='recuperar'){const result=await api.recover(v.email);status.textContent=result.message;notify(result.message);}else{await api.changePassword(v.password);api.clearSession();notify('Senha atualizada. Entre com sua nova senha.');location.hash='#login';}return;}
 if(['edital-filter','performance-filter','question-filter','error-filter','panorama-filter','exam-filter'].includes(form.id)){state.filter=v;renderView();notify('Filtros aplicados.');return;}
 if(form.id==='generate-cycle'){if(!v.student_id)throw Error('Cadastre um aluno antes de criar seu ciclo.');state.draft=suggestCycle({start:v.start,days:+v.days,hours:+v.hours,count:+v.count,subjects:fd.getAll('subjects')});const student=state.data.profiles.find(p=>p.id===v.student_id);state.draft=methodUI.applyConfig(assignTopics(state.draft,state.topics.filter(t=>t.career===student.career),state.data.progress,student.id),v.method_template);v.duration_days=+v.days;state.editCycle=null;state.draftStart=v.start;state.draftDay=v.start;renderDraft(v);document.querySelector('#cycle-draft').scrollIntoView({behavior:'smooth'});notify('Sugestão gerada. Revise os dias antes de publicar.');return;}
 if(form.id==='save-cycle'){captureDraft();const suggested=assignTopics(state.draft,draftTopics(),state.data.progress,state.draftMeta.student_id);state.draft=state.draft.map((b,i)=>b.topic_key==='follow'?{...b,topic:suggested[i].topic,topic_key:suggested[i].topic_key}:b);if(!state.draft.length)throw Error('Adicione ao menos um bloco.');if(!state.draftMeta.student_id)throw Error('Selecione um aluno cadastrado antes de salvar.');const status=submitter?.value||'Rascunho';validateCycle(state.draft,draftTopics());await writeAndReload('cycles',{student_id:state.draftMeta.student_id,title:state.draftMeta.title,notes:state.draftMeta.notes,blocks:state.draft,start_date:state.draftStart,duration_days:Math.max(1,Number(state.draftMeta.duration_days||state.draftMeta.days)||1,...state.draft.map(b=>dayNumber(b.date,state.draftStart))),status},state.editCycle);return;}
 if(form.id==='admin-password-form'){guardWrite();const result=await api.accountAction('reset-password',{student_id:form.dataset.id,password:v.password});form.reset();await loadData();renderView();notify(result.message);return;}
 if(form.dataset.commentQuestion){guardWrite();await api.save('question_comments',{student_id:state.profile.id,question_id:form.dataset.commentQuestion,body:v.body.trim()});await loadData();renderView();notify('Comentário publicado.');return;}
 if(form.id==='student-form'){await writeAndReload('profiles',{name:v.name,plan:v.plan,career:v.career,active:v.active==='true'},form.dataset.id);return;}
 if(form.id==='log-form'){const total=+v.total,correct=+v.correct;if(correct>total)throw Error('Os acertos não podem superar a quantidade de questões.');await writeAndReload('study_logs',{student_id:admin()?v.student_id:state.profile.id,date:v.date,subject:v.subject,topic:v.topic,source:v.source,total,correct,minutes:+v.minutes,notes:v.notes||'',error_reason:v.error_reason||null,origin:'external'});return;}
 if(form.id==='history-form'){await writeAndReload('history',{student_id:v.student_id,title:v.title,body:v.body,visible:fd.has('visible')});return;}
 if(form.id==='question-form'){guardWrite();if(form.dataset.examComposer){const ef=new FormData(document.querySelector('#exam-form'));state.examDraft={career:ef.get('career'),title:ef.get('title'),duration:+ef.get('duration'),description:ef.get('description'),question_ids:ef.getAll('questions')};}const options=v.options.split('\n').map(x=>x.trim()).filter(Boolean);if(options.length<2||options.length>5||+v.correct_index>=options.length)throw Error('Use de 2 a 5 alternativas e selecione um gabarito válido.');const savedQuestion=await api.rpc('save_question',{payload:{id:form.dataset.id||null,subject:v.subject,topic:v.topic,board:v.board,year:+v.year,difficulty:v.difficulty,tags:v.tags,body:v.body,options,source:v.source,correct_index:+v.correct_index,explanation:v.explanation}});state.editQuestion=null;if(form.dataset.examComposer){state.examDraft.question_ids.push(savedQuestion);state.examComposer=false;}await loadData();renderView();notify('Questão salva no banco'+(form.dataset.examComposer?' e selecionada no simulado.':'.'));return;}
 if(form.id==='answer-form'){guardWrite();state.answer=+v.answer;const r=await api.rpc('answer_question',{qid:state.activeQuestion.id,selected:+v.answer});document.querySelector('#question-result').innerHTML=`<div class="result"><strong>${r.correct?'Resposta correta':'Resposta incorreta'} · Gabarito ${String.fromCharCode(65+r.correct_index)}</strong><p>${e(r.explanation)}</p></div>`;await loadData();notify("Resposta corrigida e registrada.");return;}
 if(form.id==='note-form'){guardWrite();await api.upsert('question_notes',{student_id:state.profile.id,question_id:state.activeQuestion.id,body:v.body,highlights:state.highlights||state.data.question_notes.find(x=>x.question_id===state.activeQuestion.id)?.highlights||[]},'student_id,question_id');await loadData();notify('Anotação e grifos salvos.');return;}
 if(form.id==='error-form'){await writeAndReload('errors',{student_id:state.profile.id,subject:v.subject,topic:v.topic,reason:v.reason,source:v.source,body:v.body,explanation:v.explanation,reviewed:state.editError?.reviewed||false},form.dataset.id||undefined);state.editError=null;renderView();return;}
 if(form.id==='resource-form'){guardWrite();const file=fd.get('file');if(!file?.size&&!v.url)throw Error('Envie um arquivo ou informe um link.');if(v.url&&!safeUrl(v.url))throw Error('Informe um link HTTP ou HTTPS válido.');const storage_path=file?.size?await api.upload(file):null;await writeAndReload('resources',{title:v.title,kind:v.kind,subject:v.subject,description:v.description,url:v.url||null,storage_path});return;}
 if(form.id==='exam-form'){const ids=fd.getAll('questions');if(!ids.length)throw Error('Selecione ao menos uma questão.');guardWrite();await api.save('exams',{career:v.career,title:v.title,description:v.description,duration:+v.duration,question_ids:ids},state.editExam||undefined);state.editExam=null;state.examDraft=null;state.examComposer=false;await loadData();renderView();notify('Simulado salvo.');return;}
 if(form.id==='exam-submit'){guardWrite();await state.examSaveQueue;state.result=await api.rpc('submit_exam',{attempt_id:state.exam.attempt_id,responses:Object.fromEntries(Object.entries(v).map(([k,n])=>[k,+n]))});await loadData();renderView();notify("Simulado corrigido e resultado salvo.");return;}
}catch(err){if(form.id==='exam-submit')state.autoSubmitting=false;notify(err.message,'error');if(form.id==='auth-form'){const status=document.querySelector('#auth-status');if(status)status.textContent=err.message;}}finally{delete form.dataset.busy;submitter?.removeAttribute('disabled');}});
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(el.dataset.busy)return;el.dataset.busy='true';el.setAttribute('aria-busy','true');try{
 if(await exportUI.click(el))return;
 if(await studyUI.click(el))return;
 if(await methodUI.click(el))return;
 if(action==='dismiss-notice'){document.querySelector('#notice').textContent='';return;}
 if(action==='demo-student'||action==='demo-admin'){enterDemo(action==='demo-admin'?'admin':'student');notify("Prévia aberta.");return;}
 if(action==='logout'){await studyUI.pauseOnLeave();studyUI.reset();if(!state.demo){try{await api.logout();}catch{api.clearSession();}}state.profile=null;state.user=null;state.demo=false;Object.keys(state.data).forEach(t=>state.data[t]=[]);location.hash='#login';await route();notify('Você saiu da plataforma.');return;}
 if(action==='extend-cycle'){captureDraft();const result=extendCycle({...state.draftMeta,blocks:state.draft,start_date:state.draftStart},Number(document.querySelector('[name="extend_days"]').value),draftTopics(),state.data.progress);state.draft=result.blocks;state.draftMeta.duration_days=result.duration_days;state.draftDay=dayDate(result.first_day,state.draftStart);renderDraft(state.draftMeta);notify('Dias acrescentados seguindo a organização do ciclo e o edital. Revise e salve.');return;}
 if(action==='delete-student'){const p=state.data.profiles.find(p=>p.id===el.dataset.id);if(!confirm('Excluir definitivamente '+p.name+' e todos os registros deste aluno?')){notify('Exclusão cancelada.','info');return;}guardWrite();await api.accountAction('delete-student',{student_id:p.id});await loadData();renderView();notify('Aluno excluído.');return;}
 if(action==='format-error'){const input=document.querySelector('#error-form').elements[el.dataset.field],mark=el.dataset.mark;const text=input.value.slice(input.selectionStart,input.selectionEnd)||'texto';input.setRangeText(mark==='- '?'- '+text.replaceAll('\n','\n- '):mark+text+mark,input.selectionStart,input.selectionEnd,'select');input.focus();updateRichPreview(input);notify("Formatação aplicada. Salve o texto para guardar a alteração.");return;}
 if(action==='edit-error'){state.editError=state.data.errors.find(x=>x.id===el.dataset.id);renderView();document.querySelector('#error-form').scrollIntoView({behavior:'smooth'});notify('Erro aberto para edição.');return;}
 if(action==='compose-exam-question'){const f=new FormData(document.querySelector('#exam-form'));state.examDraft={career:f.get('career'),title:f.get('title'),duration:+f.get('duration'),description:f.get('description'),question_ids:f.getAll('questions')};state.examComposer=true;renderView();document.querySelector('#question-form').scrollIntoView({behavior:'smooth'});notify("Formulário de questão aberto.");return;}
 if(action==='edit-exam'){state.editExam=el.dataset.id;state.examDraft=structuredClone(state.data.exams.find(x=>x.id===el.dataset.id));state.examComposer=false;renderView();notify("Simulado aberto para edição.");return;}
 if(action==='delete-exam'){if(!confirm('Excluir este simulado e seus resultados? As questões permanecerão no banco.')){notify('Exclusão cancelada.','info');return;}guardWrite();await api.remove('exams',el.dataset.id);state.editExam=null;state.examDraft=null;await loadData();renderView();notify("Simulado excluído.");return;}
 if(action==='delete-comment'){if(!confirm('Apagar este comentário?')){notify('Exclusão cancelada.','info');return;}guardWrite();await api.remove('question_comments',el.dataset.id);await loadData();renderView();notify("Comentário apagado.");return;}
 if(action==='edit-student'){studentEditor(state.data.profiles.find(p=>p.id===el.dataset.id));document.querySelector('#student-editor').scrollIntoView({behavior:'smooth'});notify('Editor do aluno aberto.');return;}
 if(['edit-cycle','renew-cycle','continue-cycle'].includes(action)){const c=state.data.cycles.find(c=>c.id===el.dataset.id),student=state.data.profiles.find(p=>p.id===c.student_id);const continuing=action==='continue-cycle';state.editCycle=action==='renew-cycle'?null:c.id;state.draft=action!=='renew-cycle'?structuredClone(c.blocks):renewCycle(c,state.topics.filter(t=>t.career===student.career),state.data.progress,action==='continue-cycle');state.draftStart=action!=='renew-cycle'?(c.start_date||state.draft.map(b=>b.date).sort()[0]):state.draft.map(b=>b.date).sort()[0];const day=Number(state.data.progress.find(p=>p.student_id===c.student_id&&p.key===c.id+'|position')?.flags?.day)||1;state.draftDay=continuing?dayDate(Math.min(365,day),state.draftStart):state.draftStart;renderDraft({...c,start_date:state.draftStart,title:action!=='renew-cycle'?c.title:c.title+(action==='renew-cycle'?' · Renovação':' · Continuação')});document.querySelector('#cycle-draft').scrollIntoView({behavior:'smooth'});notify(continuing?'Ciclo retomado no Dia '+String(day).padStart(2,'0')+'. Configurações e etapas concluídas preservadas.':action==='edit-cycle'?'Ciclo aberto para edição.':'Renovação preparada. Revise e publique para o aluno.');return;}
 if(action==='remove-block'){captureDraft();state.draft.splice(+el.dataset.index,1);renderDraft(state.draftMeta);notify("Bloco removido da sugestão. Salve o ciclo para confirmar.");return;}
 if(action==='add-block'){captureDraft();addDayBlock();renderDraft(state.draftMeta);notify("Matéria adicionada ao dia. Salve o ciclo para confirmar.");return;}
 if(action==='select-draft-day'){captureDraft();state.draftDay=el.dataset.date;renderDraft(state.draftMeta);notify("Dia de estudo selecionado.");return;}
 if(action==='open-question'){state.activeQuestion=state.data.questions.find(q=>q.id===el.dataset.id);state.highlights=null;state.answer=null;renderView();notify("Questão aberta.");return;}
 if(action==='close-question'){state.activeQuestion=null;renderView();notify("Banco de questões aberto.");return;}
 if(action==='edit-question'){guardWrite();const q=state.data.questions.find(q=>q.id===el.dataset.id),answer=await api.rpc('get_question_key',{qid:q.id});state.editQuestion={...q,...answer};renderView();document.querySelector('#question-form').scrollIntoView({behavior:'smooth'});notify('Questão aberta para edição.');return;}
 if(action==='highlight'){const selection=window.getSelection(),root=document.querySelector('#question-body');if(!selection?.rangeCount||!root.contains(selection.anchorNode)||!root.contains(selection.focusNode)||selection.isCollapsed)throw Error('Selecione um trecho do enunciado primeiro.');const range=selection.getRangeAt(0),before=range.cloneRange();before.selectNodeContents(root);before.setEnd(range.startContainer,range.startOffset);const start=before.toString().length,end=start+range.toString().length;const old=state.highlights||state.data.question_notes.find(x=>x.question_id===state.activeQuestion.id)?.highlights||[];state.highlights=[...old,{start,end}];root.innerHTML=highlightBody(state.activeQuestion.body,state.highlights);selection.removeAllRanges();notify("Trecho grifado. Salve a anotação para guardar os grifos.");return;}
 if(action==='clear-highlight'){state.highlights=[];document.querySelector('#question-body').textContent=state.activeQuestion.body;notify("Grifos removidos. Salve a anotação para confirmar.");return;}
 if(action==='question-error'){const q=state.activeQuestion;state.editError=null;history.pushState(null,'','#painel/erros');await route();const f=document.querySelector('#error-form');if(!f)throw Error('Não foi possível abrir o caderno de erros.');f.elements.subject.value=q.subject;f.elements.topic.value=q.topic;f.elements.body.value=q.body;f.elements.source.value=q.source||q.board;updateRichPreview(f.elements.body);notify('Questão copiada para o formulário. Complete e salve no caderno.');return;}
 if(action==='review-error'){const r=state.data.errors.find(r=>r.id===el.dataset.id);await writeAndReload('errors',{reviewed:!r.reviewed},r.id);return;}
 if(action==='open-resource'){guardWrite();const r=state.data.resources.find(r=>r.id===el.dataset.id);const tab=window.open('about:blank','_blank');if(!tab)throw Error('O navegador bloqueou a abertura. Permita pop-ups para este site e tente novamente.');tab.opener=null;let navigated=false;try{const url=r.storage_path?await api.assetUrl(r.storage_path):safeUrl(r.url);if(!url)throw Error('Link indisponível.');await api.save('resource_views',{student_id:state.profile.id,resource_id:r.id});tab.location.href=url;navigated=true;notify('Material aberto e acesso registrado.');}catch(err){if(!navigated)tab.close();throw err;}return;}
 if(action==='start-exam'){guardWrite();const ex=state.data.exams.find(x=>x.id===el.dataset.id),attempt=await api.rpc('start_exam',{eid:ex.id});state.exam={...ex,attempt_id:attempt.id,deadline:attempt.deadline,questions:attempt.questions};state.examAnswers=attempt.answers||{};state.result=null;state.autoSubmitting=false;renderView();notify("Simulado iniciado. O tempo já está contando.");return;}
 if(action==='close-exam'){state.exam=null;state.result=null;renderView();notify("Lista de simulados aberta.");return;}
}catch(err){notify(err.message,'error');}finally{delete el.dataset.busy;el.removeAttribute('aria-busy');}});
// Preserve the user's selection when clicking the highlight toolbar.
document.addEventListener('pointerdown',event=>{if(event.target.closest('[data-action="highlight"],[data-action="format-error"]'))event.preventDefault();});
document.addEventListener('change',async event=>{const el=event.target,key=el.dataset.task||el.dataset.edital;if(!key)return;const old=state.data.progress.find(p=>p.student_id===state.profile.id&&p.key===key);try{guardWrite();if(el.dataset.edital&&el.dataset.flag==='study'&&el.checked&&!admin()){const candidate=state.data.cycles.filter(c=>c.status==='Publicado'&&c.student_id===state.profile.id).flatMap(c=>c.blocks.map(b=>({c,b}))).find(({c,b})=>'edital|'+b.topic_key===key&&(b.method?.steps||[{id:'study',kind:'study'}]).some(s=>s.kind==='study')&&dayNumber(b.date,c.start_date||c.blocks.map(x=>x.date).sort()[0])<=(Number(state.data.progress.find(p=>p.key===c.id+'|position')?.flags?.day)||1));if(candidate){const step=(candidate.b.method?.steps||[{id:'study',kind:'study'}]).find(s=>s.kind==='study');await api.rpc('record_method_action',{payload:{action:'step',cycle_id:candidate.c.id,block_id:candidate.b.id,step_id:step.id}});}}await loadData();const latest=state.data.progress.find(p=>p.student_id===state.profile.id&&p.key===key);const flags={...(latest?.flags||old?.flags||{}),[el.dataset.flag||'done']:el.checked};await api.upsert('progress',{student_id:state.profile.id,key,flags},'student_id,key');await loadData();renderView();notify('Progresso atualizado.');}catch(err){el.checked=!el.checked;notify(err.message,'error');}});
window.addEventListener('hashchange',route);
window.addEventListener('beforeunload',event=>{if(state.exam&&!state.result){event.preventDefault();event.returnValue='';}});
setInterval(()=>{if(state.exam&&!state.result&&Date.now()>=Date.parse(state.exam.deadline)&&!state.autoSubmitting){const form=document.querySelector('#exam-submit');if(form){state.autoSubmitting=true;form.requestSubmit();}}},1000);
async function boot(){try{state.topics=await fetch('/edital.json').then(r=>r.json());const params=new URLSearchParams(location.hash.slice(1));if(params.has('access_token')){api.setSession({access_token:params.get('access_token'),refresh_token:params.get('refresh_token')});if(params.get('type')==='recovery'){history.replaceState(null,'',location.pathname+'#nova-senha');}else{api.clearSession();history.replaceState(null,'',location.pathname+'#login');notify('E-mail confirmado. Entre com sua senha.');}}await route();const ctx=document.modelContext;if(ctx?.registerTool){const life=new AbortController();await ctx.registerTool({name:'navigate_mentoria',description:'Abre uma seção da plataforma, sem criar nem salvar registros.',inputSchema:{type:'object',properties:{section:{type:'string',enum:['inicio','ciclos','edital','desempenho','registros','historico','questoes','erros','materiais','simulados']}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:true},execute:async input=>{const valid=['inicio','ciclos','edital','desempenho','registros','historico','questoes','erros','materiais','simulados'];if(!state.profile||!valid.includes(input.section))throw Error('Acesso ou seção inválidos.');location.hash='#painel/'+input.section;await route();return {section:state.view};}},{signal:life.signal});window.addEventListener('pagehide',()=>life.abort(),{once:true});}}catch(err){notify('Não foi possível carregar a plataforma. '+err.message);}}
boot();

function cycleSubjectOptions(career){return [...new Set(state.topics.filter(x=>x.career===career).map(x=>x.subject))].map(s=>`<label class="check-label"><input type="checkbox" name="subjects" value="${e(s)}">${e(s)}</label>`).join('');}
function syncCycleSelection(){const form=document.querySelector('#generate-cycle');if(!form)return;const n=form.querySelectorAll('[name="subjects"]:checked').length;document.querySelector('#cycle-selection-count').textContent=n===1?'1 matéria selecionada':n+' matérias selecionadas';const count=form.elements.count;count.max=Math.max(1,n);if(n&&Number(count.value)>n)count.value=n;}
document.addEventListener('click',event=>{const action=event.target.closest('[data-action]')?.dataset.action;if(!['cycle-select-all','cycle-select-none'].includes(action))return;document.querySelectorAll('#generate-cycle [name="subjects"]').forEach(el=>el.checked=action==='cycle-select-all');syncCycleSelection();notify(action==='cycle-select-all'?'Todas as matérias foram selecionadas.':'Seleção de matérias removida.');});
document.addEventListener('change',event=>{const el=event.target,form=el.closest('#generate-cycle');if(!form)return;if(el.name==='student_id'){form.elements.cycle_career.value=state.data.profiles.find(x=>x.id===el.value)?.career||'CFO';}if(['cycle_career','student_id'].includes(el.name)){document.querySelector('#cycle-subject-options').innerHTML=cycleSubjectOptions(form.elements.cycle_career.value);}syncCycleSelection();});

function updateRichPreview(input){const preview=document.querySelector('[data-rich-preview="'+input.name+'"]');if(preview)preview.innerHTML=formattedText(input.value);}
document.addEventListener('input',event=>{if(event.target.closest('#error-form')&&['body','explanation'].includes(event.target.name))updateRichPreview(event.target);});
function passwordRequests(){const requests=state.data.password_requests.filter(r=>!r.resolved_at);return '<h2 style="margin:24px 0">Solicitações de recuperação</h2>'+(requests.map(r=>`<div class="card row"><span>${e(nameOf(r.student_id))} · Aguardando nova senha</span><button data-action="edit-student" data-id="${r.student_id}">Definir senha</button></div>`).join('')||empty('Nenhuma solicitação pendente'));}
function panoramaPage(){const students=state.data.profiles.filter(p=>p.role!=='admin'),student=admin()?(students.find(p=>p.id===state.filter.student_id)||students[0]):state.profile;if(!student)return heading('Panorama dos estudos')+empty('Cadastre um aluno para acompanhar o edital');const rows=syllabusSummary(state.topics.filter(t=>t.career===student.career),state.data.progress,student.id);const total=rows.reduce((a,r)=>a+r.total,0),studied=rows.reduce((a,r)=>a+r.study,0);return heading('Panorama dos estudos',e(student.name)+' · '+e(student.career)+' · '+studied+' de '+total+' assuntos estudados')+(admin()?`<form id="panorama-filter" class="toolbar">${profilePick(student.id)}<button>Ver aluno</button></form>`:'')+`<div class="table-wrap"><table><thead><tr><th>Matéria</th><th>Estudo</th><th>Resumo</th><th>Questões</th><th>Revisão</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${e(r.subject)}</td>${['study','summary','questions','review'].map(k=>`<td>${r[k]} / ${r.total}</td>`).join('')}</tr>`).join('')}</tbody></table></div><h2 style="margin-top:24px">O que já foi estudado</h2>${rows.map(r=>`<details><summary>${e(r.subject)} · ${r.study} assuntos</summary>${r.studied.length?r.studied.map(t=>'<p>'+e(t)+'</p>').join(''):'<p>Nenhum assunto marcado como estudado.</p>'}</details>`).join('')}${methodUI.panoramaDetails(student)}${studyUI.flashStats(student.id)}${studyUI.dayHistory(student.id)}`;}
function questionComments(qid){if(!canReviewQuestion(qid)||!state.data.questions.some(q=>q.id===qid))return '';return `<details><summary>Comentários dos alunos e do mentor</summary><p class="muted">Os comentários são compartilhados e podem discutir o gabarito.</p>${state.data.question_comments.filter(c=>c.question_id===qid).map(c=>`<div class="private-note"><small>${c.student_id===state.profile.id?'Você':admin()?e(nameOf(c.student_id)):'Participante'} · ${new Date(c.created_at).toLocaleDateString('pt-BR')}</small><p>${e(c.body)}</p>${admin()||c.student_id===state.profile.id?`<button type="button" class="small" data-action="delete-comment" data-id="${c.id}">Apagar comentário</button>`:''}</div>`).join('')||'<p>Ainda não há comentários.</p>'}<form data-comment-question="${qid}">${area('Seu comentário','body','','required maxlength="5000"')}<button>Publicar comentário</button></form></details>`;}
function resultQuestion(r,i){return `<div class="private-note"><strong>Questão ${i+1}: ${r.correct?'correta':'incorreta'} · Gabarito ${String.fromCharCode(65+r.correct_index)}</strong><p>${e(r.explanation)}</p>${questionComments(r.question_id)}</div>`;}

document.addEventListener('invalid',event=>{notify(event.target.validationMessage||'Preencha os campos obrigatórios antes de continuar.','error');},true);
document.addEventListener('click',event=>{const link=event.target.closest('a[href]');if(!link)return;const href=link.getAttribute('href');if(href.startsWith('#')){queueMicrotask(()=>notify('Seção aberta: '+(link.textContent.trim()||'Página inicial')+'.','info'));}else if(link.target==='_blank')notify('Abrindo o link em outra aba.','info');});

document.addEventListener('change',event=>{const form=event.target.closest('#edital-filter');if(!form||event.target.name!=='career')return;const ss=[...new Set(state.topics.filter(t=>t.career===event.target.value).map(t=>t.subject))];form.elements.subject.innerHTML=ss.map(subject=>'<option value="'+e(subject)+'">'+e(subject)+'</option>').join('');notify('Matérias do concurso atualizadas. Clique em Filtrar.','info');});

document.addEventListener('change',event=>{methodUI.change(event.target);studyUI.change(event.target);});
setInterval(()=>studyUI.tick(),1000);
window.addEventListener('pagehide',()=>studyUI.pauseOnLeave());
document.addEventListener('input',event=>methodUI.input(event.target));
function canReviewQuestion(id){if(admin())return true;const exams=state.data.exams.filter(ex=>ex.question_ids.includes(id));return !exams.length||exams.some(ex=>state.data.exam_attempts.some(a=>a.exam_id===ex.id&&a.student_id===state.profile.id&&a.submitted_at));}

document.addEventListener('change',event=>{const el=event.target;if(!el.closest('#exam-submit')||el.type!=='radio'||!state.exam)return;state.examAnswers[el.name]=+el.value;const attempt=state.exam.attempt_id;state.examSaveQueue=(state.examSaveQueue||Promise.resolve()).catch(()=>{}).then(()=>api.rpc('save_exam_answer',{attempt_uuid:attempt,qid:el.name,selected:+el.value})).then(()=>notify('Resposta do simulado salva.','info')).catch(err=>notify('Não foi possível salvar esta resposta. '+err.message,'error'));});

document.addEventListener('change',event=>{const el=event.target;if(el.name==='log_topic_key'){const t=state.topics.find(t=>syllabusKey(t)===el.value),form=el.closest('form');if(t&&form){form.elements.subject.value=t.subject;form.elements.topic.value=t.title;notify('Assunto vinculado ao edital.','info');}}if(el.closest('#log-form')&&el.name==='student_id'){const p=state.data.profiles.find(p=>p.id===el.value);el.closest('form').elements.log_topic_key.innerHTML='<option value="">Preencher manualmente</option>'+state.topics.filter(t=>t.career===p?.career).map(t=>'<option value="'+e(syllabusKey(t))+'">'+e(t.subject+' · '+t.title)+'</option>').join('');}});
